      padding: 22px;
      margin-bottom: 18px;
    }

    .question-title {
      margin: 0 0 10px;
      font-size: 1.06rem;
      letter-spacing: -0.01em;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
