        const correctValues = correct.map((input) => input.value).sort().join('|');

        if (selectedValues === correctValues) {
          correctQuestions += 1;
        }
      });

      result.innerHTML = `You got <strong>${correctQuestions} out of 3</strong> questions right.`;
    });
  </script>
</body>
</html>
