   <script>
     const form = document.getElementById('quiz-form');
     const result = document.getElementById('result');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const questions = ['q1', 'q2', 'q3'];
       let correctQuestions = 0;

       questions.forEach((name) => {
         const selected = [...form.querySelectorAll(`input[name="${name}"]:checked`)];
         const correct = [...form.querySelectorAll(`input[name="${name}"][data-correct="true"]`)];

         const selectedValues = selected.map((input) => input.value).sort().join('|');
         const correctValues = correct.map((input) => input.value).sort().join('|');

         if (selectedValues === correctValues) {
           correctQuestions += 1;
         }
       });

       result.innerHTML = `You got <strong>${correctQuestions} out of 3</strong> questions right.`;
     });
